1	// import 与 readings 两个子命令的实现。
2	
3	import { readFileSync } from 'node:fs';
4	import { CsvError, parseCsv } from './csv.ts';
5	import { loadStore, saveStore, StoreError, dataFilePath, type Reading } from './store.ts';
6	import { formatIsoUtc, parseIso8601 } from './time.ts';
7	import { formatKwh, parseKwh } from './value.ts';
8	
9	export const CSV_HEADER = 'device,time,reading';
10	
11	function err(message: string): void {
12	  console.error(`meterwatch: ${message}`);
13	}
14	
15	/**
16	 * 导入 CSV 文件。整批成功或整批拒绝:
17	 * 任一行格式错误或读数冲突都不写入任何新数据。
18	 * 返回进程退出码。
19	 */
20	export function cmdImport(file: string): number {
21	  const storePath = dataFilePath();
22	
23	  let existing: Reading[];
24	  try {
25	    existing = loadStore(storePath);
26	  } catch (e) {
27	    if (e instanceof StoreError) {
28	      err(e.message);
29	      return 1;
30	    }
31	    throw e;
32	  }
33	
34	  let text: string;
35	  try {
36	    text = readFileSync(file, 'utf8');
37	  } catch (e) {
38	    err(`cannot read '${file}': ${(e as Error).message}`);
39	    return 1;
40	  }
41	
42	  let records;
43	  try {
44	    records = parseCsv(text);
45	  } catch (e) {
46	    if (e instanceof CsvError) {
47	      err(`${file}: ${e.message}`);
48	      return 1;
49	    }
50	    throw e;
51	  }
52	
53	  if (records.length === 0) {
54	    err(`${file}: empty file, expected header '${CSV_HEADER}'`);
55	    return 1;
56	  }
57	  const header = records[0];
58	  if (header.fields.length !== 3 || header.fields.join(',') !== CSV_HEADER) {
59	    err(`${file}: line ${header.line}: expected header '${CSV_HEADER}'`);
60	    return 1;
61	  }
62	
63	  // 逐行解析,收集全部格式错误。
64	  const errors: string[] = [];
65	  const rows: Array<Reading & { line: number }> = [];
66	  for (const rec of records.slice(1)) {
67	    if (rec.fields.length !== 3) {
68	      errors.push(`line ${rec.line}: expected 3 fields (device,time,reading), got ${rec.fields.length}`);
69	      continue;
70	    }
71	    const device = rec.fields[0].trim();
72	    if (device === '') {
73	      errors.push(`line ${rec.line}: device identifier is empty`);
74	      continue;
75	    }
76	    const ts = parseIso8601(rec.fields[1].trim());
77	    if (ts === null) {
78	      errors.push(`line ${rec.line}: invalid timestamp '${rec.fields[1].trim()}' (need ISO8601 with seconds and Z or numeric offset, e.g. 2026-01-01T00:00:00Z)`);
79	      continue;
80	    }
81	    const milli = parseKwh(rec.fields[2].trim());
82	    if (milli === null) {
83	      errors.push(`line ${rec.line}: invalid reading '${rec.fields[2].trim()}' (need a non-negative kWh value with at most 3 decimals)`);
84	      continue;
85	    }
86	    rows.push({ device, ts, milli, line: rec.line });
87	  }
88	  if (errors.length > 0) {
89	    for (const e of errors) err(`${file}: ${e}`);
90	    err(`import rejected: ${errors.length} invalid row(s); nothing was imported`);
91	    return 1;
92	  }
93	
94	  // 去重与冲突检测:先文件内部,再与已存数据比对。身份 = (设备, 实际时刻)。
95	  const key = (device: string, ts: number): string => `${device} ${ts}`;
96	  const inStore = new Map<string, number>();
97	  for (const r of existing) inStore.set(key(r.device, r.ts), r.milli);
98	
99	  const inFile = new Map<string, number>();
100	  const toAdd: Reading[] = [];
101	  const conflicts: string[] = [];
102	  let duplicates = 0;
103	  for (const r of rows) {
104	    const k = key(r.device, r.ts);
105	    const at = formatIsoUtc(r.ts);
106	    const fileVal = inFile.get(k);
107	    if (fileVal !== undefined) {
108	      if (fileVal === r.milli) {
109	        duplicates++;
110	      } else {
111	        conflicts.push(`line ${r.line}: conflicting readings for device '${r.device}' at ${at} (${formatKwh(fileVal)} vs ${formatKwh(r.milli)} kWh)`);
112	      }
113	      continue;
114	    }
115	    inFile.set(k, r.milli);
116	    const storeVal = inStore.get(k);
117	    if (storeVal !== undefined) {
118	      if (storeVal === r.milli) {
119	        duplicates++;
120	      } else {
121	        conflicts.push(`line ${r.line}: conflicts with stored reading for device '${r.device}' at ${at} (stored ${formatKwh(storeVal)} vs new ${formatKwh(r.milli)} kWh)`);
122	      }
123	      continue;
124	    }
125	    toAdd.push({ device: r.device, ts: r.ts, milli: r.milli });
126	  }
127	  if (conflicts.length > 0) {
128	    for (const c of conflicts) err(`${file}: ${c}`);
129	    err(`import rejected: ${conflicts.length} conflict(s); nothing was imported`);
130	    return 1;
131	  }
132	
133	  try {
134	    saveStore(storePath, existing.concat(toAdd));
135	  } catch (e) {
136	    if (e instanceof StoreError) {
137	      err(e.message);
138	      return 1;
139	    }
140	    throw e;
141	  }
142	  console.log(`imported ${toAdd.length} new reading(s), ${duplicates} duplicate(s) skipped`);
143	  return 0;
144	}
145	
146	export interface ReadingsFilter {
147	  devices: string[];
148	  from?: number;
149	  to?: number;
150	}
151	
152	/**
153	 * 查询读数与消耗。只读,不修改数据。
154	 * 前驱取自完整已存时序(可能在范围之外);区间归属结束时刻。
155	 * 返回进程退出码。
156	 */
157	export function cmdReadings(filter: ReadingsFilter): number {
158	  const storePath = dataFilePath();
159	  let all: Reading[];
160	  try {
161	    all = loadStore(storePath);
162	  } catch (e) {
163	    if (e instanceof StoreError) {
164	      err(e.message);
165	      return 1;
166	    }
167	    throw e;
168	  }
169	
170	  const byDevice = new Map<string, Reading[]>();
171	  for (const r of all) {
172	    const list = byDevice.get(r.device);
173	    if (list) list.push(r);
174	    else byDevice.set(r.device, [r]);
175	  }
176	  for (const list of byDevice.values()) list.sort((a, b) => a.ts - b.ts);
177	
178	  const wanted =
179	    filter.devices.length > 0
180	      ? [...new Set(filter.devices)]
181	      : [...byDevice.keys()];
182	  wanted.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
183	
184	  let printed = false;
185	  for (const device of wanted) {
186	    const series = byDevice.get(device);
187	    if (!series) continue;
188	    const selected: Array<{ r: Reading; prev: Reading | null }> = [];
189	    for (let i = 0; i < series.length; i++) {
190	      const r = series[i];
191	      if (filter.from !== undefined && r.ts < filter.from) continue;
192	      if (filter.to !== undefined && r.ts >= filter.to) continue;
193	      selected.push({ r, prev: i > 0 ? series[i - 1] : null });
194	    }
195	    if (selected.length === 0) continue;
196	    printed = true;
197	
198	    console.log(`device: ${device}`);
199	    let total = 0;
200	    for (const { r, prev } of selected) {
201	      let line = `  ${formatIsoUtc(r.ts)}  reading=${formatKwh(r.milli)} kWh`;
202	      if (prev === null) {
203	        line += '  interval=n/a  consumption=n/a (no predecessor)';
204	      } else {
205	        const duration = r.ts - prev.ts;
206	        const diff = r.milli - prev.milli;
207	        line += `  interval=${formatIsoUtc(prev.ts)}..${formatIsoUtc(r.ts)} (${duration}s)`;
208	        if (diff < 0) {
209	          line += `  consumption=ANOMALY: decrease of ${formatKwh(-diff)} kWh (excluded from summary)`;
210	        } else {
211	          line += `  consumption=${formatKwh(diff)} kWh`;
212	          total += diff;
213	        }
214	      }
215	      console.log(line);
216	    }
217	    console.log(`  summary: device=${device}  total consumption=${formatKwh(total)} kWh`);
218	  }
219	  if (!printed) console.log('no readings match');
220	  return 0;
221	}
222	
223	export { parseIso8601 };
224

